// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 depositAmount, uint256 preBalance) public {
        vm.assume(depositAmount > 0 && depositAmount <= 1e36);
        vm.assume(preBalance <= 1e36);

        Helper helper = new Helper();

        vm.deal(address(helper), preBalance);

        vm.deal(address(helper), preBalance + depositAmount);
        vm.startPrank(address(helper));
        c.addToBalance{value: depositAmount}();
        uint256 balBefore = c.getBalance(address(helper));
        c.withdrawBalance();
        uint256 balAfter = c.getBalance(address(helper));
        uint256 received = helper.receivedEther();
        vm.stopPrank();

        assertTrue(balBefore > 0 ? (balAfter == 0 && received == balBefore) : true);
    }
}

contract Helper {
    uint256 public receivedEther;
    receive() external payable {
        receivedEther = msg.value;
    }
}
